using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitHeldDeliveryTests
{
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:unit-held/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);return s;}
    static long ArmyEnd(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds);
    static WorldSession Failed(bool known=true){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().Delivered);if(known)At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);return s;}
    static WorldSession HomeReady(){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(ArmyEnd(s),j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);return s;}
    static TroopDispatch Query(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();
    static TroopReceipt Answer(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last();
    static UnitPostInquiryAnswer Quote(ContractWorld w){var r=w.NewMilitary!.UnitInquiry!.Receipts.Last();return ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body));}
    static void Ask(WorldSession s,NewMilitaryAction action=NewMilitaryAction.InquireUnitKnown,bool policy=true){var r=s.DecideNewMilitary(Input(s,action) with{PostPolicy=policy?NewGameMilitary.UnitReplyRecoveryContract:null},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void MoveAway(WorldSession s){var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+5000,home.Y)},s.PlayerControl,s.Revision).Code);}
    static WorldSession FailedReply(bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Ask(s,policy:policy);At(s,Query(s).DueAt);MoveAway(s);At(s,Answer(s).ReplyDueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Replies.Last().Received);return s;}
    static void AtPersonEnd(WorldSession s){var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);}
    static void WalkTo(WorldSession s,FieldPoint p){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=p},s.PlayerControl,s.Revision).Code);AtPersonEnd(s);}
    static WorldSession AtHeldOriginal(bool retryFirst=false){var s=FailedReply();var report=s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single();if(retryFirst)Send(s,NewMilitaryAction.PersonalHome);At(s,report.DueAt);if(retryFirst)At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Last().DueAt);WalkTo(s,Query(s).Destination);return s;}
    static WorldSession AtMissedReport(){var s=HomeReady();Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+5000,a.Y),B=new(a.X+5000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);long start=s.Seconds;Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart) with{MotionContract=NewGameMilitary.RoutContract},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);var w=s.DiagnosticSnapshot();var known=w.NewMilitary!.Withdrawal!.Sightings.Last().Position;var path=RegionalGround.Plan(NewGameMilitary.PersonPosition(w,s.Seconds),known,s.Seconds,courier:true,atlas:true);long delay=Math.Max(1,(path.LastOrDefault()?.EndAt??s.Seconds)-s.Seconds);long send=start+9-delay;Assert.True(send>=s.Seconds,"fixture must reach home before the last pre-rout inquiry window");At(s,send);Ask(s);At(s,Query(s).DueAt);Assert.True(Answer(s).Delivered);MoveAway(s);At(s,Answer(s).ReplyDueAt);var report=Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights);At(s,report.DueAt);var journey=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(s.Seconds,(journey.Route.LastOrDefault()?.EndAt??s.Seconds)+1));return s;}
    [Fact]public void PhysicalOriginalBeforeRetryIsOneFormalReceipt(){var s=AtHeldOriginal();var w=s.DiagnosticSnapshot();var r=Answer(s);Assert.DoesNotContain(w.Messaging.Receipts,x=>x.MessageId==r.ReplyMessage);string body=w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body;int orders=w.NewMilitary!.Orders.Length;Assert.True(NewGameMilitary.HeldAllowed(w,NewMilitaryAction.TakeHeldReply));Send(s,NewMilitaryAction.TakeHeldReply);var t=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Assert.True(t.Route.Length==0||t.Route.Last().EndAt<=t.DueAt);At(s,t.DueAt);w=s.DiagnosticSnapshot();Assert.True(w.Messaging.Attempts.Single(a=>a.Id==t.Attempt).ArrivedLate);Assert.Single(w.Messaging.Receipts,a=>a.MessageId==r.ReplyMessage);Assert.Equal(body,w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body);Assert.False(w.NewMilitary!.UnitInquiry!.Replies.Last().Received);Assert.Equal(orders,w.NewMilitary.Orders.Length);At(s,s.Seconds+50);Assert.Single(s.DiagnosticSnapshot().Messaging.Receipts,a=>a.MessageId==r.ReplyMessage);}
    [Fact]public void RetryThenPhysicalOldCopyDoesNotRepeatKnowledgeOrReceipt(){var s=AtHeldOriginal(true);var r=Answer(s);var original=s.DiagnosticSnapshot().Messaging.Receipts.Single(a=>a.MessageId==r.ReplyMessage);long learned=MessageFlow.LearnedAt(s.DiagnosticSnapshot().Messaging,r.ReplyMessage,s.PlayerControl.Value)!.Value;Send(s,NewMilitaryAction.TakeHeldReply);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(original,w.Messaging.Receipts.Single(a=>a.MessageId==r.ReplyMessage));Assert.Equal(learned,MessageFlow.LearnedAt(w.Messaging,r.ReplyMessage,w.PlayerControl.Value));Assert.Single(w.Messaging.Knowledge,k=>k.MessageId==r.ReplyMessage&&k.CharacterId==w.PlayerControl.Value);}
    [Fact]public void RemotePaperDoesNotMakePickupAvailable(){var s=FailedReply();At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single().DueAt);string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.False(NewGameMilitary.HeldAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.TakeHeldReply));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.TakeHeldReply),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void PickupInputIsIdempotent(){var s=AtHeldOriginal(true);var i=Input(s,NewMilitaryAction.TakeHeldReply);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void HandoverRestoresSameFuture(int step){var s=AtHeldOriginal(true);Send(s,NewMilitaryAction.TakeHeldReply);if(step>0)At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);if(step>1)At(s,s.Seconds+1);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));long until=s.Seconds+5;foreach(var x in new[]{s,c})At(x,until);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedPhysicalTransferIsRejected(int kind){var s=AtHeldOriginal(true);Send(s,NewMilitaryAction.TakeHeldReply);if(kind==3)At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.HeldDelivery!;if(kind==0)x.Transfers[0]=x.Transfers[0] with{Origin=new(0,0)};if(kind==1)x.Transfers[0]=x.Transfers[0] with{Cargo=[]};if(kind==2)x.Transfers[0]=x.Transfers[0] with{DueAt=x.Transfers[0].DueAt+1};if(kind==3)x.Arrivals[0]=x.Arrivals[0] with{Received=false};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldHeldPaperSaveOmitsNewTransferModule(){var s=AtHeldOriginal(true);string json=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot().NewMilitary));Assert.DoesNotContain("HeldDelivery",json);Assert.Null(ContractJson.Read<NewMilitaryState>(System.Text.Encoding.UTF8.GetBytes(json)).HeldDelivery);}
    [Fact]public void PhysicalReportCarriesAllPapersButDoesNotOpenThemForPlayer(){var s=AtMissedReport();Assert.Equal(2,NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds).Length);var r=Answer(s);Send(s,NewMilitaryAction.ReturnHeldReportHome);var t=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Assert.Equal(2,t.Cargo.Length);Assert.Equal(NewGameMilitary.Home(s.DiagnosticSnapshot(),0),t.Destination);if(t.DueAt>s.Seconds+1){At(s,t.DueAt-1);var held=NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds);Assert.Equal(2,held.Length);Assert.Single(held.Select(h=>h.Position).Distinct());Assert.NotEqual(t.Origin,held[0].Position);}At(s,t.DueAt);var w=s.DiagnosticSnapshot();Assert.True(w.NewMilitary!.HeldDelivery!.Arrivals.Last().Received);Assert.True(MessageFlow.FailureKnown(w.Messaging,r.ReplyAttempt,NewGameMilitary.UnitIds[0].Value));Assert.False(MessageFlow.Knows(w.Messaging,r.ReplyMessage,w.PlayerControl.Value));var remaining=Assert.Single(NewGameMilitary.HeldPapers(w,s.Seconds));Assert.Equal(t.Destination,remaining.Position);Assert.Equal(r.ReplyMessage,remaining.Message);Assert.Equal(UnitReplyLeg.Retry,w.NewMilitary.ReplyRecovery!.Flights.Last().Kind);}
    [Fact]public void ReplyPickupBeforeReportReturnSuppressesUnneededRetry(){var s=AtMissedReport();var r=Answer(s);Send(s,NewMilitaryAction.TakeHeldReply);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);Assert.True(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,r.ReplyMessage,s.PlayerControl.Value));Send(s,NewMilitaryAction.ReturnHeldReportHome);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Assert.True(MessageFlow.FailureKnown(w.Messaging,r.ReplyAttempt,NewGameMilitary.UnitIds[0].Value));Assert.DoesNotContain(w.NewMilitary!.ReplyRecovery!.Flights,f=>f.Kind==UnitReplyLeg.Retry);Assert.Empty(NewGameMilitary.HeldPapers(w,s.Seconds));Assert.Single(w.Messaging.Receipts,x=>x.MessageId==r.ReplyMessage);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void LongReportJourneyRestoresAllCargo(int step){var s=AtMissedReport();Send(s,NewMilitaryAction.ReturnHeldReportHome);var t=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Assert.True(t.DueAt>s.Seconds+1);At(s,step==0?s.Seconds+1:step==1?t.DueAt-1:t.DueAt);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,c})At(x,t.DueAt+3);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Fact]public void RecipientLeavingHandoverDoesNotCreateReceipt(){var s=AtHeldOriginal(true);var p=NewGameMilitary.PersonPosition(s.DiagnosticSnapshot(),s.Seconds);WalkTo(s,new(p.X+900,p.Y));Send(s,NewMilitaryAction.TakeHeldReply);var t=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(p.X+5900,p.Y)},s.PlayerControl,s.Revision).Code);At(s,t.DueAt);var w=s.DiagnosticSnapshot();Assert.True(RegionalGround.Distance(NewGameMilitary.PersonPosition(w,s.Seconds),t.Destination)>1000,"fixture must actually leave recipient range before the carrier arrives");Assert.False(w.NewMilitary!.HeldDelivery!.Arrivals.Last().Received);Assert.Equal(AttemptStatus.Rejected,w.Messaging.Attempts.Single(a=>a.Id==t.Attempt).Status);Assert.Contains(NewGameMilitary.HeldPapers(w,s.Seconds),h=>h.Attempt==t.Attempt);var c=new WorldSession(ContractJson.Copy(w));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
}
